/* Fahrlehrer-Kompass · Lernszenen auf Englisch (Texte einfach, "you"; Erzähler-Fassung, fachgeprüft 18.11.2026). Wird von lernszenen.js über window.LernszenenEN genutzt. */
window.LernszenenEN = {"auffahren":{"titel":"Joining the Autobahn","kurz":"Speed up, find a gap, merge","phasen":[{"titel":"The slip road","text":"The slip road curves round to the Autobahn. Start watching the traffic there now. How fast are the others, and where are the gaps?","frage":{"text":"Who has priority when you merge?","optionen":["Me, because I am on the acceleration lane","The cars that drive straight on the Autobahn","Whoever is faster"],"erklaerung":"The cars on the through carriageway have priority. You must let them pass."}},{"titel":"Pick up speed","text":"Now you speed up quickly on the acceleration lane, to match the traffic. Here you may go faster than on the through lanes. That is intended.","frage":{"text":"What matters most now?","optionen":["I drive slowly and wait","I quickly get up to the speed of the traffic","I move over to the left straight away"],"erklaerung":"With a similar speed to the traffic you can merge safely. If you are too slow, you force others to brake."}},{"titel":"Indicator left","text":"Then you signal the change in good time and clearly. Indicator left.","frage":{"text":"When do you indicate?","optionen":["Only when I am already changing lanes","In good time beforehand","Not at all, it is obvious"],"erklaerung":"You signal every lane change clearly and in good time."}},{"titel":"Choose the gap","text":"The truck is ahead on the right. The red car keeps well back, so the gap behind the truck fits. Adjust your speed and keep enough distance. As a rule of thumb, keep half your speed in metres.","frage":{"text":"Where do you merge?","optionen":["Next to the truck","Into the gap behind the truck","In front of the truck, I put my foot down"],"erklaerung":"The gap behind the truck is big enough. In front of it would be tight, and the truck has priority."}},{"titel":"Mirrors and shoulder check","text":"Pay attention. Shortly before you change, look in the rear view mirror and the side mirror. Then do a shoulder check to the left. Otherwise you cannot see the blind spot.","frage":{"text":"What comes right before the lane change?","optionen":["I turn the radio down","I look in the mirrors and do a shoulder check to the left","I honk the horn"],"erklaerung":"Only with a shoulder check do you see who is in the blind spot."}},{"titel":"Merging","text":"And now you cross the wide dashed line. Never cross the solid line or the hatched area. Move over briskly and smoothly. Do not wait until the end of the lane."},{"titel":"Indicator off, keep distance","text":"Done, you are across. Indicator off, and keep driving on the right. Keep at least half your speed in metres behind the truck ahead.","frage":{"text":"And now?","optionen":["I overtake on the left right away","I turn the indicator off, drive on the right and keep my distance","I carry on along the hard shoulder"],"erklaerung":"You must drive on the right and keep enough distance."}},{"titel":"To remember","text":"When you join the Autobahn, the zip merge rule does not apply. Give priority to the traffic there. If there is no gap, stop at the end of the lane if you have to. Never swerve onto the hard shoulder."}]},
"abfahren":{"titel":"Leaving the Autobahn","kurz":"Move right in good time, use the deceleration lane, brake only there","phasen":[{"titel":"Exit announced","text":"The sign announces the exit one thousand metres ahead. Plan now. Move early into the right lane, not at the last second from the left.","frage":{"text":"When do you move to the right?","optionen":["Right at the exit","Early, at the latest before the countdown markers","It does not matter, across the hatched area if needed"],"erklaerung":"Get in lane in good time. Then you can change calmly, without putting anyone in danger."}},{"titel":"Mirrors, indicator, shoulder check","text":"So, now we move over to the right. Rear view mirror, side mirror, indicator right, shoulder check to the right. Then move briskly into the right lane."},{"titel":"Get into the right lane","text":"Stay on the right and keep your speed. Indicator off again."},{"titel":"Sign at 500 metres","text":"And here the exit is announced once more, five hundred metres ahead. From now on, avoid overtaking if you can."},{"titel":"Countdown markers","text":"Do you see the markers? Three, two and one stripe show three hundred, two hundred and one hundred metres to the deceleration lane.","frage":{"text":"What does the marker with two stripes mean?","optionen":["200 metres to go to the exit","Speed 200","Two lanes free"],"erklaerung":"Three stripes are 300 metres, two are 200 metres and one is 100 metres."}},{"titel":"Indicator right","text":"Check your mirror and indicate right in good time before the deceleration lane. The traffic behind you should see it early."},{"titel":"Mirrors, shoulder check, across","text":"Then mirrors, shoulder check to the right, and across the wide dashed line onto the deceleration lane."},{"titel":"Brake only now","text":"Only on the deceleration lane do you brake, not before on the Autobahn. On this lane you must not go faster than on the through lanes.","frage":{"text":"Where do you slow down?","optionen":["Already in the right lane","On the deceleration lane","Only in the bend"],"erklaerung":"Braking on the Autobahn endangers the drivers behind you. Brake only on the deceleration lane, before the bend, down to the speed shown."}},{"titel":"Bend and speedometer","text":"Slow down to speed sixty by the sign, before the bend gets tighter. After a long Autobahn drive, speed sixty feels very slow. Look at the speedometer.","frage":{"text":"Why do you look at the speedometer?","optionen":["Because after fast driving I can easily misjudge my speed","Because of the fuel gauge","I do not need to"],"erklaerung":"After the Autobahn you underestimate your own speed. You have got used to it."}},{"titel":"To remember","text":"And if you miss the exit? Then drive on to the next one. Never reverse or turn round on the Autobahn, not even on the hard shoulder."}]},
"reissverschluss":{"titel":"Zip merge when a lane ends","kurz":"Use both lanes up to the narrowing, then merge in turn","phasen":[{"titel":"Lane ends","text":"Look, the sign shows that the right lane ends. You still use both lanes up to the narrowing.","frage":{"text":"When do you move left?","optionen":["As soon as I see the sign","Right before the narrowing starts","Not at all, the others must wait"],"erklaerung":"You merge right before the narrowing, always in turn."}},{"titel":"Drive up to the front","text":"Do not change too early. If you drive on the right up to the narrowing, you use the road properly. That keeps the queue shorter."},{"titel":"Indicate and look for a gap","text":"Indicate left and adjust your speed to the line of cars on the left. Pick the car you will go in behind."},{"titel":"Merge in turn","text":"So, just before the narrowing you check your mirror and do a shoulder check. Then you merge in turn behind a car on the left. The drivers on the left always let one car in.","frage":{"text":"Who has to let whom in?","optionen":["Nobody, first come first served","The drivers on the left always let one car in, in turn","Whoever drives on the right must wait until everything is clear"],"erklaerung":"In a zip merge, cars take turns. One from the left, one from the right."}},{"titel":"To remember","text":"Remember, the zip merge applies when a lane ends or is blocked. On the acceleration lane of an Autobahn slip road it does not apply. There the through traffic has priority."}]},
"rettungsgasse":{"titel":"Emergency corridor","kurz":"Already when traffic is crawling, the far left lane goes left, all others go right","phasen":[{"titel":"Traffic slows","text":"The traffic gets slower. If you are only at walking pace or everyone has stopped, you form the emergency corridor. Do not wait for the blue lights.","frage":{"text":"When do you form the emergency corridor?","optionen":["Only when I hear the siren","As soon as traffic is at walking pace or stops","Only for accidents ahead of me"],"erklaerung":"At walking pace or standstill, and right away."}},{"titel":"Which way to move?","text":"Look, the corridor forms between the far left lane and the lane directly to its right. If you drive in the far left lane, you move left. Everyone else moves right.","frage":{"text":"You are in the middle lane of three. Which way?","optionen":["I move to the left","I move to the right","I stay where I am"],"erklaerung":"Everyone except the far left lane moves to the right."}},{"titel":"Emergency vehicle coming","text":"Now you see blue lights and hear the siren. Make way at once. Stay put and do not shuffle back and forth. The corridor must be straight and clear."},{"titel":"Keep the corridor open","text":"The emergency vehicle has passed. Keep the corridor clear anyway, because often more are coming. Do not follow it!","frage":{"text":"The ambulance has passed. And now?","optionen":["I follow it, then it goes faster","I keep the corridor open, more may come","I go straight back into my lane"],"erklaerung":"The emergency corridor stays until the traffic flows again."}},{"titel":"To remember","text":"Remember, the hard shoulder is not a lane for the impatient. If you do not form the corridor or drive in it yourself, you risk a fine, points and a driving ban."}]},
"laengs":{"titel":"Reverse parallel parking","kurz":"Sideways into a parking space at the kerb","phasen":[{"titel":"Check the space","text":"Does the space fit? As a rule of thumb you need a good car length plus about one and a half metres. Indicate right early, so the traffic behind you knows what you are doing.","frage":{"text":"When do you put the indicator on?","optionen":["Only when reversing","Already when approaching the space","Not at all, I am only parking"],"erklaerung":"Indicate right early. Then the traffic behind you understands why you stop."}},{"titel":"Stop next to the car","text":"Stop parallel next to the car in front, about fifty centimetres to one metre away. Your rear is about level with its rear.","frage":{"text":"What comes before reversing?","optionen":["I reverse straight away","I look all round, especially behind","I honk the horn"],"erklaerung":"Look all round before every movement. When reversing, you turn your body and look through the rear window."}},{"titel":"Full lock right","text":"Roll back slowly and steer fully right. Your rear swings into the space. Look behind. Your front swings out left into the road, so check again first that nobody is coming."},{"titel":"Straight back","text":"Then you straighten the steering wheel and roll straight back a little. That brings the car closer to the kerb."},{"titel":"Steer the other way","text":"When your right front corner is past the rear of the car in front, steer fully left. Then the car turns parallel to the kerb.","frage":{"text":"When do you steer left?","optionen":["Right at the start","When my front is past the car in front","Not at all"],"erklaerung":"If you steer the other way too early, you bump the car in front. Too late, and the rear touches the kerb."}},{"titel":"Straighten up","text":"At the end, roll forward a little until there is about the same room at the front and back. You are parallel and close to the kerb, as a guide up to about thirty centimetres. You must not touch it.","frage":{"text":"How far may the car be from the kerb?","optionen":["It does not matter","Close, as a guide up to about 30 centimetres","At least 1 metre"],"erklaerung":"Well parked means parallel and close to the kerb, but without touching."}}],"anleitung":"You are next to the car in front of the space. Indicator right, look all round, put it in reverse. Hold down the gas and steer first fully right, then straight, then fully left. The yellow lines show you the way."},
"quer_rueck":{"titel":"Reverse bay parking","kurz":"Reverse into a bay, later drive out forwards with a good view","phasen":[{"titel":"Past the space","text":"Drive slowly along the aisle, indicate right and drive past the space, until your rear is about one to two metres past it."},{"titel":"Look all round","text":"Before you reverse, look all round. Watch for pedestrians and cars in the aisle!","frage":{"text":"Why do you reverse into the bay?","optionen":["Later, when I drive out, I have a good view ahead","It is required","Because it is faster"],"erklaerung":"Reversing in, you can steer tighter. And when driving out, you see the cross traffic."}},{"titel":"Full lock","text":"Now roll back slowly and steer fully right. Look behind and at the corners of the neighbouring cars."},{"titel":"Straight back","text":"When the car is parallel to its neighbours, straighten the steering wheel. Then roll back, centred, to the end of the space.","frage":{"text":"When do you straighten the steering wheel?","optionen":["As soon as I am in the space","When the car is parallel to the neighbouring cars","Never"],"erklaerung":"Then you carry on straight, otherwise the car sits at an angle."}}],"anleitung":"Reverse parking. Look all round, put it in reverse and steer fully right. When the car is parallel, drive straight back."},
"quer_vor":{"titel":"Forward bay parking","kurz":"Forward into a bay, with a swing out first","phasen":[{"titel":"Drive past and swing out","text":"Drive slowly along the aisle up to the space and indicate right. Swing out a little to the left, so that the curve into the space fits.","frage":{"text":"Why do you swing out before parking forwards?","optionen":["So that the curve fits into the narrow space","Because it is faster","I do not need to"],"erklaerung":"When driving forwards, the rear wheels cut the corner inwards. If you swing out, the rear does not scrape the neighbouring car."}},{"titel":"Full lock","text":"When the middle of the space is about level with your side mirror, steer fully right. Watch the corners of the neighbouring cars and do a shoulder check to the right."},{"titel":"Straight in","text":"Now you straighten the steering wheel and roll into the space, centred, until the front stops shortly before the end. People must be able to get out on both sides.","frage":{"text":"What is the disadvantage later when driving out?","optionen":["None","Reversing out, with a poor view of the traffic","I need more petrol"],"erklaerung":"That is why reverse parking is recommended. Then you drive out forwards later and can see well."}}],"anleitung":"Forward parking. Swing out slightly to the left, then steer fully right and drive straight into the space. Look all round before you set off."},
"wenden":{"titel":"Three-point turn","kurz":"Turn round going forwards and backwards in a narrow street","phasen":[{"titel":"Prepare","text":"Stop at the right edge. Check that turning round is allowed here and that you can see well. Indicate left and look in both directions.","frage":{"text":"What matters most when turning round?","optionen":["As few moves as possible","Look in both directions before every move","Finish quickly"],"erklaerung":"When turning round, you must not put anyone in danger. Looking carefully is the most important thing."}},{"titel":"First move, forwards full left","text":"And now the first move. Move off slowly and steer fully left, until just before the kerb opposite. Shortly before stopping, you already steer back to the right."},{"titel":"Second move, backwards full right","text":"Second move. Put it in reverse and look all round again. Roll back slowly and steer fully right, until just before the kerb behind you.","frage":{"text":"Which way do you steer when reversing?","optionen":["Left","Right, the rear should go right","Not at all"],"erklaerung":"When reversing, you turn the steering wheel to where the rear should go."}},{"titel":"Third move, forwards out to the left","text":"Third move. Look all round again, steer fully left and drive off in the new direction. Then move over to the right."},{"titel":"To remember","text":"Very important, do not steer while standing still. Steer while the car rolls slowly. How many moves you need is not so important. You must not touch the kerb."}],"anleitung":"Three-point turn. Indicator left, look all round, forwards with full lock left. Then reverse with full lock right, then forwards out to the left. Do not touch the kerb!"},
"ecke":{"titel":"Reversing round a corner to the right","kurz":"Reverse into a side street, always close to the kerb","phasen":[{"titel":"Stop past the junction","text":"So, now you stop on the right at the edge of the road, about two to three car lengths past the junction. Look all round once. The traffic has priority.","frage":{"text":"What matters most when reversing?","optionen":["I drive as fast as possible","I drive slowly and look all round","I look only in the rear view mirror"],"erklaerung":"When you reverse, nobody may be put in danger. You drive slowly and look behind and all round."}},{"titel":"Straight back","text":"Turn your upper body and look through the rear window. Then roll straight back, about fifty centimetres from the kerb."},{"titel":"Steer round the corner","text":"As soon as the rear wheel reaches the corner, you steer right. That way the car follows the curve of the kerb. The front swings left onto the road. Look all round once more beforehand.","frage":{"text":"Which way do you steer so that the rear goes right?","optionen":["I steer to the right","I steer to the left"],"erklaerung":"When reversing, you turn the steering wheel to where the rear should go."}},{"titel":"Straight on","text":"When the car is parallel to the kerb of the side street, you straighten the steering wheel. Then you reverse about one more car length."}],"anleitung":"Put it in reverse, look all round, straight back. At the corner you steer right and follow the kerb. Then straight into the side street."},
"gefahr":{"titel":"Emergency braking, 30 or 50?","kurz":"Reaction distance plus braking distance make the stopping distance, plus a reaction test","phasen":[{"titel":"Two cars, same reaction","text":"Two drives in the same lane. You drive at speed fifty. The transparent car shows you at speed thirty. In a moment a ball rolls into the road between parked cars. A child runs after it."},{"titel":"Danger and reaction time","text":"About one second passes until your foot is on the brake. In that time the car keeps going without braking. At speed fifty that is almost fourteen metres, at speed thirty a good eight metres.","frage":{"text":"How long is the reaction distance at 50 kilometres per hour, by the rule of thumb?","optionen":["I calculate 5 metres","I calculate 15 metres","I calculate 25 metres"],"erklaerung":"The rule is 50 divided by 10, times 3. That is 15 metres. Worked out exactly, it is about 14 metres per second."}},{"titel":"Full braking","text":"Now you push brake and clutch fully down together and keep the pressure on. The anti-lock brakes rattle, that is how it should be. Keep a loose grip on the steering wheel, so you can steer round.","frage":{"text":"How long is the braking distance in an emergency stop from 50 kilometres per hour, by the rule of thumb?","optionen":["I calculate 12.5 metres","I calculate 25 metres","I calculate 50 metres"],"erklaerung":"50 divided by 10 gives 5. 5 times 5 is 25, divided by 2 that is 12.5 metres. A normal braking distance without danger is 25 metres long."}},{"titel":"The result","text":"The car at speed thirty stops in time. At speed fifty the distance is not enough. Where the ball lies, it would still be doing about thirty five kilometres per hour. Speed thirty saves lives.","frage":{"text":"Why is speed 30 so important near schools?","optionen":["I am thinking of the noise","The stopping distance is much shorter. At 50, at the spot where I would already stand at 30, I am still almost as fast as at the start","I think it is only a recommendation"],"erklaerung":"The faster you drive, the longer the braking distance. It grows with the square of the speed."}}]},
"ueberholen":{"titel":"Overtaking on a country road","kurz":"Check your view, let oncoming traffic pass, overtake briskly, pull back in with a gap","phasen":[{"titel":"Slow truck ahead","text":"Look, outside built-up areas one hundred kilometres per hour is allowed. Ahead of you a truck drives at sixty. Keep enough distance. That way you can see past it and build up speed.","frage":{"text":"When are you allowed to overtake?","optionen":["I always overtake when I am faster","Only if I can see that oncoming traffic will not be hindered at any point, and I am much faster","I only overtake on the right"],"erklaerung":"You may only overtake if oncoming traffic will definitely not be hindered and you are much faster."}},{"titel":"Oncoming traffic","text":"A car is coming towards you. Do not pull out now. Wait.","frage":{"text":"About how much clear road do you need to overtake a truck doing 60 at 100 kilometres per hour?","optionen":["I need about 100 metres","I need about 250 metres. In that time the oncoming traffic comes the same distance towards me again. So I need around 500 metres of clear view","I need about 50 metres"],"erklaerung":"The vehicle lengths and the gap before and after make about 100 metres. You multiply that by 100 and divide by 40, the difference in speed. That gives about 250 metres. In the same time the oncoming traffic comes the same distance towards you again."}},{"titel":"Mirrors, indicator, shoulder check","text":"Is everything clear, with a good view and no solid line? Then look in the rear view mirror and the side mirror and indicate left. Just before you pull out, do a shoulder check to the left."},{"titel":"Pass briskly","text":"Right, now pull out and accelerate briskly. The speed limit is still the limit. Leave enough space to the side of the truck.","frage":{"text":"The truck speeds up while you overtake. Is it allowed to?","optionen":["Yes","No. Whoever is being overtaken must not speed up"],"erklaerung":"Whoever is being overtaken must not increase their speed."}},{"titel":"Indicator right, pull back in","text":"Once you can see the whole truck in the rear view mirror, indicate right and move back to the right. Do not cut in close in front of it."},{"titel":"No overtaking ahead","text":"And here are the no overtaking sign and a solid line. Overtaking is forbidden here, for example before crests and bends. If you have already started overtaking, you must finish before you get there.","frage":{"text":"Are you allowed to cross the solid centre line to overtake?","optionen":["Yes, I may cross it briefly","No, I must not cross it","I may cross it only for tractors"],"erklaerung":"You must not cross the solid line."}}]},
"schulbus":{"titel":"School bus with hazard lights","kurz":"No overtaking, walking pace only, oncoming traffic too, and expect children","phasen":[{"titel":"School bus with hazard lights","text":"Look, the school bus drives towards the stop with hazard lights on. You must not overtake it now.","frage":{"text":"Are you allowed to overtake the bus while it drives towards the stop with hazard lights on?","optionen":["Yes, if the road is clear, I overtake","No, I do not overtake","I only overtake with the horn"],"erklaerung":"You must not overtake public buses or school buses that drive towards a stop with hazard lights on."}},{"titel":"Bus stops, children get out","text":"The bus stops and the children get out. It is best to stop first, well back behind the bus. Children are unpredictable. They can run into the road behind or in front of the bus."},{"titel":"Walking pace","text":"Then you pass only at walking pace, that is about four to seven kilometres per hour. Keep enough distance so nobody is put in danger. That also applies to oncoming traffic.","frage":{"text":"Does walking pace apply to oncoming traffic too?","optionen":["No, I drive at walking pace only in my own direction","Yes. Even with oncoming traffic on the same carriageway I drive only at walking pace","I drive at walking pace only on school days"],"erklaerung":"Walking pace also applies to oncoming traffic on the same carriageway."}},{"titel":"Child runs into the road","text":"Watch out, a child runs across the road in front of the bus. Stop at once. If necessary, you wait.","frage":{"text":"What do you do?","optionen":["I swerve and drive on","I stop and wait until the child is safely across","I honk the horn"],"erklaerung":"If necessary, you wait. You must be sure nobody is put in danger, not even the passengers."}},{"titel":"Bus pulls away","text":"The bus now indicates left, because it wants to leave the stop. Let it pull away. If necessary, you wait."}]},
"rvl":{"titel":"Priority to the right in a speed 30 zone","kurz":"Who goes first? Three cars at a junction without signs","phasen":[{"titel":"Junction without signs","text":"Look, in a speed thirty zone there are almost never priority signs. Here priority to the right applies. Approach slowly, so you can stop.","frage":{"text":"Which rule applies at this junction?","optionen":["I think priority to the right applies","I think the wider road has priority","I think whoever is there first goes"],"erklaerung":"Without signs, traffic lights or police, priority to the right applies. Whoever comes from the right has priority."}},{"titel":"Who goes first?","text":"Right, now all three have stopped. Everyone looks to the right. Whoever has nobody there may go first.","frage":{"text":"Tap the cars in the order in which they may go.","erklaerung":"Blue has nobody on its right and goes first. Then it is your turn, because blue was on your right. Red goes last, because you were on red's right.","namen":{"b":"Blue, from the right","fs":"You","c":"Red, turning left"}}},{"titel":"Blue goes","text":"The blue car has nobody on its right. It goes first."},{"titel":"Then you","text":"Now nobody is on your right. You drive straight across the junction."},{"titel":"Red last","text":"Last, red goes and turns left. It had to wait, because you came from the right."},{"titel":"To remember","text":"And one more important thing. If you have to wait, show it in good time. Do this by driving up at a moderate speed. If there are cars on all four sides, work it out together. One of you gives way."}]},
"links_gegen":{"titel":"Turning left with oncoming traffic","kurz":"Oncoming traffic and oncoming right turners have priority","phasen":[{"titel":"Get in lane","text":"First you look in the mirror, indicate left and move towards the middle. Check the traffic behind you before that.","frage":{"text":"Where do you position yourself to turn left?","optionen":["I position myself far right","I position myself up to the middle of the road","I position myself on the opposite carriageway"],"erklaerung":"To turn left, you position yourself up to the middle. In one-way streets you drive as far left as possible."}},{"titel":"Wait in the junction","text":"Then you drive forward into the junction and wait. Your wheels stay straight. If you are hit from behind, you do not roll into oncoming traffic.","frage":{"text":"Tap the vehicles in the order they may go.","erklaerung":"Whoever turns left lets the oncoming traffic through, including the car turning right from opposite. You go last.","namen":{"g1":"Blue, straight on","g3":"Red, turning right","g2":"Van, straight on","fs":"You, turning left"}}},{"titel":"Let oncoming traffic through","text":"Oncoming traffic going straight has priority, and so does the right turner from opposite. Turn only when everything is clear and no pedestrian is still crossing the road."},{"titel":"Watch for pedestrians","text":"See, in the street you turn into, a pedestrian walks across the road. Take special care and wait until they are across.","frage":{"text":"The pedestrian is still on the road. What do you do?","optionen":["I honk the horn","I wait until they have passed","I drive through just behind them"],"erklaerung":"When turning, you take special care of pedestrians. If necessary, you wait."}},{"titel":"Shoulder check left","text":"Right before turning, do a shoulder check to the left. Cyclists may be there, or someone overtaking you. Then you turn briskly in a wide curve."}]},
"voreinander":{"titel":"Two left turners in front of each other","kurz":"If you face each other and both turn left, you turn in front of each other","phasen":[{"titel":"Two left turners","text":"Look, you and the red car both want to turn left. You are facing each other.","frage":{"text":"How do the two turn?","optionen":["We turn in front of each other. Each turns in front of the other","We turn around each other","I turn first if I am there first"],"erklaerung":"Oncoming left turners turn in front of each other. They only do it differently if the traffic or the shape of the junction requires it."}},{"titel":"Turning in front of each other","text":"You set off at the same time and turn in front of each other, right side to right side. That saves time. But the red car blocks your view of the oncoming traffic behind it. Be especially alert."},{"titel":"To remember","text":"And remember one more thing. You turn around each other only if markings, the traffic light or the shape of the junction demand it."}]},
"rechts_rad":{"titel":"Turning right with a cycle path","kurz":"Shoulder check, the cyclist going straight has priority","phasen":[{"titel":"Get right and indicate","text":"First you look in the mirror, indicate right and get as far right as possible. A cycle path runs to the right of the road.","frage":{"text":"Who has priority here?","optionen":["I have priority, I am faster","The cyclist going straight has priority","I have priority if I reach the junction first"],"erklaerung":"When you turn, you must let cyclists through who ride beside the road in the same direction."}},{"titel":"Shoulder check right","text":"Right before turning, look in the mirror once more and over your right shoulder. A cyclist can be in the blind spot."},{"titel":"Wait","text":"Watch out, the cyclist comes from behind and goes straight. Stop and let them through. Only then do you turn right in a tight curve.","frage":{"text":"What do you do now?","optionen":["I turn quickly before the cyclist","I stop and let them through","I honk so they brake"],"erklaerung":"The cyclist has priority. Accidents with cyclists when turning right are among the worst in city traffic."}},{"titel":"Turn and keep watching","text":"You turn only when everything is clear. While turning, keep looking for cyclists and pedestrians. The next cyclist is already coming."}]},
"doppel":{"titel":"Turning left from two lanes","kurz":"Two turning lanes. Everyone stays in their lane.","phasen":[{"titel":"Two lanes to the left","text":"Look, both lanes lead to the left. The arrows on the road show it. The light is green. Check your mirror, indicate and get in lane in good time. Then stay in your lane.","frage":{"text":"You are in the right of the two left turn lanes. Which lane do you turn into?","optionen":["I turn into the right lane of the new road","I turn into the left lane","It doesn't matter"],"erklaerung":"Left stays left, right stays right. That way you don't get in each other's way."}},{"titel":"Staying in your lane through the curve","text":"Right, now you all turn smoothly side by side. The dashed lines in the junction show you the way. In the junction you never change lanes."},{"titel":"After the turn","text":"And only after the junction may you change lanes, if needed. Check your mirror, indicate and do a shoulder check."}]},
"kreisel":{"titel":"Roundabout","kurz":"Enter without indicating. Traffic in the circle has priority. When leaving, you indicate.","phasen":[{"titel":"The roundabout sign","text":"Before the roundabout you see the give way sign, and under it the roundabout sign. Whoever is already in the circle has priority. Approach slowly and look to the left.","frage":{"text":"Do you indicate when entering the roundabout?","optionen":["Yes, I indicate right","Yes, I indicate left","No, I must not indicate when entering"],"erklaerung":"When entering, indicating is not allowed."}},{"titel":"Giving way","text":"Do you see the blue car? It is already in the circle and has priority. Stop at the give way line and let it pass."},{"titel":"Entering","text":"When it is clear, you go in without indicating. In the circle you drive anticlockwise. And you must not stop there."},{"titel":"Indicate right to leave","text":"Now it is time to leave. Once you pass the exit before yours, you check your mirror and indicate right. Just before you leave, a shoulder check to the right. Watch out for cyclists and pedestrians.","frage":{"text":"When do you indicate to leave?","optionen":["I do not indicate at all","I indicate after the exit before mine, in good time before leaving","I already indicate when entering"],"erklaerung":"You announce that you are leaving. Indicate right as soon as you have passed the exit before yours."}},{"titel":"Pedestrians at the zebra crossing","text":"Careful, behind the exit there is a zebra crossing. Whoever wants to use it has priority. Approach at moderate speed only, and wait.","frage":{"text":"The pedestrian wants to cross at the zebra crossing. Who has priority?","optionen":["Me, I am coming from the roundabout","The pedestrian has priority","Whoever is faster has priority"],"erklaerung":"Anyone who clearly wants to use the zebra crossing must be able to get across. You let her cross."}}]},
"zebra":{"titel":"Zebra crossing","kurz":"Look ahead and be ready to brake. Anyone who wants to cross has priority.","phasen":[{"titel":"Zebra crossing ahead","text":"Up ahead there is a zebra crossing. Ease off the accelerator early and look at the pavements. Does someone want to cross? Children are small and hard to see.","frage":{"text":"How do you approach a zebra crossing when someone clearly wants to cross?","optionen":["I carry on as normal, they have to wait","I approach only at moderate speed and wait if needed","I sound the horn and drive through"],"erklaerung":"You let the pedestrians cross. Approach only at moderate speed and wait if needed."}},{"titel":"Stopping","text":"See, the pedestrians start to walk. Stop before the zebra crossing, not on it. You must not drive past the waiting car, and you must not overtake.","frage":{"text":"The car in front of you stops at the zebra crossing. May you overtake it on the left?","optionen":["Yes, if I am fast","No, I must not overtake at a zebra crossing","Yes, if I sound the horn"],"erklaerung":"Nobody may overtake at a zebra crossing."}},{"titel":"Only when it is clear","text":"And drive on only when everyone has safely left the zebra crossing, also on the other side. Eye contact helps."},{"titel":"To remember","text":"One more thing to remember. If traffic queues behind the zebra crossing, do not drive onto it when you would have to wait there."}]},
"eng":{"titel":"Narrow spot, obstacle on your side","kurz":"Whoever has to get past the obstacle lets the oncoming traffic through first.","phasen":[{"titel":"Obstacle ahead","text":"Look, a truck is standing on your side with its hazard lights on. The road is too narrow for two vehicles side by side.","frage":{"text":"Who may go through the narrow spot first?","optionen":["Me, I was there first","The oncoming traffic, the obstacle is on my side","Whoever is faster goes first"],"erklaerung":"Whoever wants to pass the obstacle on the left lets the oncoming traffic through first."}},{"titel":"Waiting at a distance","text":"So stop in good time and keep your distance from the obstacle. That leaves room to drive past, and you see the oncoming traffic better."},{"titel":"Indicating before pulling out","text":"And when it is clear, check your mirror and indicate left. Then do a shoulder check to the left and pass the truck with enough space to the side. Watch out for people getting out."},{"titel":"Moving back in","text":"There, now you are past. After the obstacle you indicate right and move back over to the right."}]},
"stop":{"titel":"Stop sign","kurz":"Always stop completely at the stop line, then edge forward.","phasen":[{"titel":"Stop, give way","text":"Here is a stop sign. You stop at the stop line, every time, even if it is clear. After that you give way.","frage":{"text":"At the stop sign, must you stop even if you can see that it is clear?","optionen":["No, rolling slowly is enough","Yes, I always stop completely","Only at night do I have to stop"],"erklaerung":"You must stop. The wheels must come to a complete stop."}},{"titel":"Standing still at the stop line","text":"So, now the car is at the stop line and the wheels are not moving. From here you often cannot see enough yet."},{"titel":"Edging forward","text":"So you roll slowly up to the line of sight and stop again. Look left, right, left.","frage":{"text":"Your view is blocked at the stop line. What now?","optionen":["I just drive off","I edge forward slowly and look again","I sound the horn"],"erklaerung":"After stopping at the stop line, you may carefully edge forward to the line of sight."}},{"titel":"Letting the cross traffic through","text":"The two vehicles on the priority road have priority. Only when it is clear do you turn right."}]},
"gruenpfeil":{"titel":"Green arrow sign at a red light","kurz":"First stop, then turn right carefully. Whoever has green goes first.","phasen":[{"titel":"Red and a sign with a green arrow","text":"Look, the traffic light shows red. To the right of it hangs a sign with a green arrow on black metal. That is not a lit arrow in the traffic light.","frage":{"text":"What does the green arrow ask of you first?","optionen":["I roll through slowly","I stop completely at the stop line","Nothing, it shows green"],"erklaerung":"After stopping, you may turn right at red. You must stop."}},{"titel":"Stopping at the stop line","text":"So you stop completely. In front of you a woman crosses the road on green.","frage":{"text":"Who may go first?","optionen":["Me, I have the arrow","The pedestrians and the cross traffic with green","Whoever was there first"],"erklaerung":"You must not hinder or endanger anyone. This applies above all to pedestrians and to traffic that has green."}},{"titel":"Edging forward to the line of sight","text":"Now the pedestrian crossing is clear. Roll slowly up to the line of sight and stop again."},{"titel":"Cross traffic has green","text":"But careful, from the left comes a car with green. You must not hinder or endanger it. So you wait."},{"titel":"Turning","text":"There, the blue car has passed. Do a shoulder check to the right and turn slowly. You may only do this from the right lane."},{"titel":"To remember","text":"And one more thing to remember. A lit green arrow in the traffic light is a green phase of its own. At the sign with the green arrow you stop first. Then you turn with the greatest care."}]},
"abknick":{"titel":"Priority road that bends","kurz":"The priority road makes a curve. Whoever follows it indicates and has priority.","phasen":[{"titel":"The priority road bends","text":"Look, the yellow band is the priority road. It bends from south to east. The extra sign under the priority road sign shows the course. Whoever follows it has priority in the curve too.","frage":{"text":"Who has priority here?","optionen":["Everyone who follows the course of the priority road","Whoever comes from the right","Whoever is there first"],"erklaerung":"The priority road sign with the extra sign applies to the whole course. Whoever follows the priority road has priority."}},{"titel":"Red has to wait","text":"Here the red car comes from the side road. That road has the give way sign. It has to wait and shows that too. It wants to go straight on and gets in the way of both cars on the priority road.","frage":{"text":"The red car wants to go straight on. Who has to wait?","optionen":["The red car, it comes from the side road","I have to wait","The blue car"],"erklaerung":"The vehicles on the priority road go first, even when they turn."}},{"titel":"Indicate here too","text":"And now to you. You stay on the priority road. Even if you only follow its course, you must indicate. And watch out especially for pedestrians.","frage":{"text":"You follow the priority road to the right. Do you have to indicate?","optionen":["No, I stay on the priority road","Yes, I am turning","I indicate only in the dark"],"erklaerung":"With the extra sign for the course of the priority road, you must indicate when you follow it. The indicator shows the waiting driver what you are going to do."}},{"titel":"Opposite direction on the priority road","text":"The blue car comes from the east. It follows the priority road to the left and indicates. The blue car has priority too. You both keep right and meet like oncoming traffic."},{"titel":"Now the red car may go","text":"Only when nobody is coming any more on the priority road does the red car drive off. And you? When you turn in, better look both ways once more."}]},
"vorfahrt_gewaehren":{"titel":"Give way sign","kurz":"Edge forward slowly, check your view, let the cross traffic through.","phasen":[{"titel":"The give way sign","text":"The triangle means give way. Unlike at the stop sign, you do not always have to stop. But you approach so slowly that you can stop at any time. On the left a garage blocks the view.","frage":{"text":"What is the difference from the stop sign?","optionen":["There is no difference","At the triangle I stop only if traffic comes, at the stop sign always","At the triangle I have priority"],"erklaerung":"At the stop sign you must always stop. At the triangle you give way and stop only if needed."}},{"titel":"Slowing down","text":"So you ease off the accelerator early and are ready to brake. Start looking left and right now. Behind the garage a car may already be close."},{"titel":"Edging forward slowly","text":"Careful, your view to the left is blocked. Roll forward step by step until you can see far enough. In an emergency you stop at once. Never drive in blind.","frage":{"text":"You see nothing to the left because the garage is in the way. What do you do?","optionen":["I accelerate, they will let me go anyway","I edge forward slowly until I can see","I sound the horn and go"],"erklaerung":"If you cannot see whether someone with priority is coming, you may carefully edge into the junction."}},{"titel":"Letting the cross traffic through","text":"And now traffic comes. The blue car from the left, right after it the red one from the right. Both have priority. You stay put and let both through.","frage":{"text":"Traffic comes from both sides. When do you go?","optionen":["I go as soon as the first car has passed","I go when it is clear from both sides","I go when I have sounded the horn"],"erklaerung":"Only when nobody you would hinder is coming from the left or right."}},{"titel":"Shoulder check and turning","text":"Good, now it is clear. The indicator is already on. Do one more shoulder check, then drive briskly onto the road and adjust your speed."}]},
"rechts_fussg":{"titel":"Turning right with pedestrians","kurz":"The pedestrians in the side road have green and priority too.","phasen":[{"titel":"Green for both","text":"You have green and want to turn right. But the pedestrians in the side road have green at the same time. Whoever turns lets them through.","frage":{"text":"You have green. Who has priority on the pedestrian crossing of the side road?","optionen":["Me, I have green","The pedestrians, they walk on green","Whoever is faster"],"erklaerung":"When turning, you must let pedestrians through, even if you have green yourself."}},{"titel":"Shoulder check right, slowly","text":"Now you turn. Check your mirror and do a shoulder check to the right. Cyclists can be in the blind spot. Drive very slowly round the corner and watch for the pedestrians while you turn."},{"titel":"Waiting before the crossing","text":"The first pedestrians are already on the crossing. You stop before it and let them walk in peace. Do not sound the horn, do not rush them.","frage":{"text":"Pedestrians are still on the crossing. What do you do?","optionen":["I drive past in front of them quickly","I stop and let them through","I sound the horn so they walk faster"],"erklaerung":"You must take special care of pedestrians. If needed, you wait."}},{"titel":"The next one comes too","text":"And there a child follows, a little later. Children and older people are slower. Drive off only when everyone is really across."},{"titel":"Only when the crossing is clear","text":"Now everyone is on the pavement. Look once more and pull away slowly. Here too the pedestrians go first."}]},
"grundstueck":{"titel":"From the driveway onto the road","kurz":"The flowing traffic has priority, also the pedestrians on the pavement.","phasen":[{"titel":"Indicator, then look all around","text":"You are on the property and want to get onto the road. First indicate right, then look all around. You must not endanger anyone. Traffic on the pavement and the road has priority.","frage":{"text":"Who has priority, you from the driveway or the traffic on the pavement and the road?","optionen":["Me, I was there first","The flowing traffic, also the pedestrians on the pavement","Whoever sounds the horn louder"],"erklaerung":"Whoever drives out of a property must not endanger anyone. The traffic on the pavement and the road has priority."}},{"titel":"View blocked, someone guides you","text":"The wall on the left hides the pavement, and you cannot see the road yet. You drive at walking pace. If the view stays bad, let someone guide you. Here the guide stands at the edge in a safety vest."},{"titel":"Pedestrian on the pavement","text":"See, a pedestrian is coming from behind the wall. He walks on the pavement past the driveway. You stop before the pavement and let him pass.","frage":{"text":"A pedestrian passes your driveway on the pavement. What do you do?","optionen":["I quickly drive through in front of him","I stop and let him pass","I sound the horn"],"erklaerung":"The pedestrian has priority. The car stays put until he has passed."}},{"titel":"Edging forward slowly","text":"Now the pavement is clear. You roll very slowly up to the kerb, until you can see the road in both directions."},{"titel":"Flowing traffic first","text":"The blue car comes from the left, and soon after the red one from the right. Both drive past. You wait until the road is clear in both directions.","frage":{"text":"When do you drive onto the road?","optionen":["I go when the gap is big enough that nobody has to brake","I go as soon as the first car has passed","I sound the horn and go"],"erklaerung":"Nobody may have to brake or swerve because of you. Otherwise you wait."}},{"titel":"Shoulder check left and merging","text":"Good, the road is clear. Shoulder check to the left, because of the cyclists. Then turn right and get up to speed briskly. You switch off the indicator only when you are on the road."}]},
"ampel_gelb":{"titel":"Amber and red with amber","kurz":"At amber you stop before the junction if it is safe. Red and amber is still red.","phasen":[{"titel":"Green, but ready to brake","text":"You drive towards a traffic light at speed fifty. It is still green, but you are already watching it. How long has it been green? Your foot stays close to the brake."},{"titel":"Amber, decide now","text":"Now the light changes to amber. Amber means wait before the junction. You are about forty five metres from the stop line. Is that enough to stop?","frage":{"text":"Amber, the stop line is still about 45 metres away, you drive at speed 50. What do you do?","optionen":["I accelerate, I can still make it","I brake, I can stop safely","I drive on, amber is like green"],"erklaerung":"Amber means wait before the junction. 45 metres is enough to stop here."}},{"titel":"The blue car was already too close","text":"At amber the blue car was only about eighteen metres from the line. That is not enough to stop, and hard braking would be dangerous. Whoever can no longer stop safely drives on.","frage":{"text":"At amber the blue car is only 18 metres from the stop line. What is right?","optionen":["I brake hard, no matter what happens behind me","I drive on, stopping safely is no longer possible","I accelerate more to get across faster"],"erklaerung":"Only if you can no longer stop safely may you drive through. If in doubt, you brake."}},{"titel":"Red, stop and stopping distance","text":"You stop with five metres to spare, and the cross traffic has green. At speed fifty the stopping distance is about forty metres. Fifteen metres reaction distance, twenty five metres braking distance.","frage":{"text":"How long is the stopping distance at speed 50, by the rule of thumb?","optionen":["I think it is about 15 metres","I think it is about 40 metres","I think it is about 100 metres"],"erklaerung":"50 divided by 10 is 5. 5 times 3 is 15 metres reaction distance. 5 times 5 is 25 metres braking distance. Together about 40 metres."}},{"titel":"Red and amber, still red","text":"Now the light shows red and amber together. That means it will be green soon. But you still have to wait. Press the clutch and put it in first gear. But do not drive off yet.","frage":{"text":"The light shows red and amber. What applies?","optionen":["I drive off, it will be green soon","I keep waiting, it is still red","I reverse"],"erklaerung":"Red and amber still counts as red. Only at green may you go."}},{"titel":"Green, pulling away","text":"And there is green. Look once to the left and right to see whether anyone still wants to get through. Then pull away briskly."}]},
"bahnuebergang":{"titel":"Level crossing with St Andrew's cross","kurz":"A red flashing light and a barrier mean wait, even after the train, never go round the barrier.","phasen":[{"titel":"St Andrew's cross, rail vehicles have priority","text":"Look, before the level crossing there is a St Andrew's cross. Slow down, stay ready to brake and look to both sides along the track.","frage":{"text":"What does the St Andrew's cross mean?","optionen":["Rail vehicles have priority, I let them go first","I have priority, the train must brake","I think priority to the right applies here"],"erklaerung":"The St Andrew's cross shows that rail vehicles have priority. A train cannot swerve and brakes only very slowly."}},{"titel":"Red flashing light, stop","text":"The red light flashes. That means stop. Stop in good time before the St Andrew's cross. Do not try to get across quickly.","frage":{"text":"The red light starts to flash. What do you do?","optionen":["I quickly drive across","I stop before the St Andrew's cross","I sound the horn and roll through"],"erklaerung":"A red flashing light means wait. Whoever quickly drives across risks their life and the lives of the passengers."}},{"titel":"The barrier comes down","text":"Now the half barrier comes down. You stop a good distance before it. Not on the tracks, not under the barrier, not beside it."},{"titel":"The train comes","text":"A train comes from the south. It is fast and cannot stop. You stay calmly where you are and wait."},{"titel":"Train gone, still wait","text":"The train has gone, but the barrier is still down and the light still flashes. On a second track another train may come. Drive only when the barrier is open.","frage":{"text":"The train has gone, the barrier is still down. May you drive round the barrier?","optionen":["Yes, I may, the train is gone","No, I wait until the barrier is open","Yes, I may, but only slowly"],"erklaerung":"Never drive round barriers or under them. Only when the barrier is open and the light goes out is the way clear."}},{"titel":"The barrier goes up","text":"Now the barrier rises, but the flashing light is still on. Wait a moment longer until it is off."},{"titel":"Clear, check the space behind","text":"Light off, barrier open. Before you drive, look whether there is room behind the track. You drive only if you can leave the level crossing completely.","frage":{"text":"Behind the crossing the traffic is queuing. Do you drive onto the crossing?","optionen":["Yes, I drive onto it, it will move on soon","No, I drive only if I can leave the crossing completely","Yes, I drive, the barrier is open"],"erklaerung":"On a level crossing you must not stop. Whoever stays on the track in a jam is in mortal danger."}},{"titel":"If the car breaks down","text":"If the car stops on the track, get out at once, all of you, and move away from the track. Then call one one two, or the number on the sign. Move the car off the track last, if you can."}]},
"strassenbahn":{"titel":"Tram at the stop","kurz":"When the tram stops, passengers walk across the road. You stop and then pass only at walking pace.","phasen":[{"titel":"Stop with a tram","text":"The tram runs on its tracks in the middle of the road. You let it pass. At the stop you pass only carefully. Expect passengers on the road.","frage":{"text":"The tram brakes before the stop. What do you expect?","optionen":["I expect passengers walking across the road to and from the tram","I expect nothing, the tram runs on rails","I have a clear road"],"erklaerung":"At stops, passengers get on and off and often walk across the lane. You prepare for that already while approaching."}},{"titel":"Tram stops with hazard lights","text":"Now the tram stands still with its hazard lights on. Passengers get on and off and come across your lane. You stop and let them through.","frage":{"text":"Passengers walk across your lane. What do you do?","optionen":["I sound the horn and drive through","I stop and wait until the passengers are on the pavement or in the tram","I squeeze slowly past them"],"erklaerung":"If needed, you wait. You must not endanger passengers, even if they are in a hurry."}},{"titel":"Watch out for children","text":"Careful, a child is still running to the tram. Children often run off suddenly. You stay put until everyone is safe. Do not pull away too early."},{"titel":"Passing at walking pace","text":"Now the passengers are gone. You pass the stopped tram carefully. While passengers get on or off, you pass on the right only at walking pace and keep your distance. If needed, you stop.","frage":{"text":"How fast may you pass the stopped tram on the right if passengers get on or off?","optionen":["I may drive 30 kilometres per hour","I drive at most walking pace","I drive as fast as allowed"],"erklaerung":"If passengers get on or off, you may pass the stopped tram on the right only at walking pace and keeping your distance. If needed, you wait."}},{"titel":"Tram pulls away","text":"Then the tram pulls away. Keep the tracks clear and let the tram through. This also applies if you want to turn and cross the tracks while doing so."}]},
"abstand":{"titel":"Safe distance","kurz":"Half the speedometer reading as distance. Whoever drives too close runs into the car in front when it brakes.","phasen":[{"titel":"Half the speedometer reading","text":"Two drivers follow the car ahead at speed fifty. For the distance, take half the speedometer reading in metres. At speed fifty that is twenty five metres, at speed one hundred it is fifty.","frage":{"text":"You drive at speed 80. How much distance do you need by the rule of thumb?","optionen":["I keep 8 metres distance","I keep 40 metres distance","I keep 80 metres distance"],"erklaerung":"Half the speedometer reading means 80 divided by 2, so 40 metres. When it is raining or wet, much more."}},{"titel":"The red car is too close","text":"The red car drives only ten metres behind the white car. At speed fifty that is less than one second of distance. It looks fine, as long as nothing happens."},{"titel":"The car in front brakes","text":"Both cars ahead brake suddenly. Until you react, about one second passes. In that time, at speed fifty, you roll about fourteen metres, the yellow stretch. Then comes the emergency stop, the red one.","frage":{"text":"How far does your car roll at speed 50 during one second of reaction time?","optionen":["I think it is about 5 metres","I think it is about 14 metres","I think it is about 25 metres"],"erklaerung":"Speed 50 is about 14 metres per second. In the reaction time you already roll 14 metres without braking."}},{"titel":"Reaction distance plus braking distance","text":"You brake with a twenty five metre gap and stop with room to spare. For the red car the gap is not enough. Its stopping distance is longer than the gap."},{"titel":"Too close means a rear end crash","text":"Look at the speedometer of the red car. It hits the car in front at about twenty eight kilometres per hour. Keep enough distance to stop behind the car in front, even if it brakes suddenly."},{"titel":"The two second rule","text":"Count one thousand and one, one thousand and two, when the car in front passes a spot. Only then may you be there. Or take half the speedometer reading. More when wet, in the dark and with a trailer."}]},
"halteverbot":{"titel":"No stopping and no parking","kurz":"Along a road. Where may you stop and where not?","phasen":[{"titel":"Where may you stop?","text":"You look for a place to park. Red means no stopping and no parking. Pink means only parking is forbidden, stopping briefly is allowed. Now you drive the stretch step by step."},{"titel":"Side road","text":"Look, before and after a side road or junction you must not park, five metres each from the point where the road edges meet. Stopping briefly is allowed there, parking is not.","frage":{"text":"How far before and after a side road is parking not allowed?","optionen":["I think 1 metre","I think 5 metres","I think 20 metres"],"erklaerung":"5 metres before and after the point where the road edges meet, you must not park. This applies at junctions and side roads."}},{"titel":"Zebra crossing","text":"On the zebra crossing and up to five metres before it you must not stop. A car standing there blocks the view for pedestrians and drivers.","frage":{"text":"May you stop briefly 3 metres before the zebra crossing to let someone out?","optionen":["Yes, I may stop briefly","No, up to 5 metres before it I must not stop","Yes, I may stop with the hazard lights"],"erklaerung":"Before the zebra crossing, the last 5 metres are a no stopping zone. Even stopping briefly is not allowed."}},{"titel":"Driveway to a property","text":"Before an entrance or exit of a property you must not park. Stopping briefly is allowed. Whoever parks there locks the residents in or out."},{"titel":"Absolute no stopping","text":"Careful, from the sign on you must not stop and must not park. Not even briefly to get out.","frage":{"text":"May you stop briefly to get out in an absolute no stopping zone?","optionen":["Yes, I may stop for up to 3 minutes","No, I must not stop","Yes, I may stop with the hazard lights"],"erklaerung":"The sign forbids stopping completely. You may stop here only if the traffic forces you to."}},{"titel":"Limited no stopping","text":"Here you may stop for up to three minutes. For getting in or out, or loading and unloading, also longer, but without delay. Otherwise you are parking, and that is banned here up to the next side road.","frage":{"text":"How long may you stop in a limited no stopping zone?","optionen":["I must not stop at all","I may stop for up to 3 minutes","I may stop as long as I like"],"erklaerung":"In a limited no stopping zone you may stop for up to 3 minutes. For getting in and out or for loading and unloading also longer, but without delay. If you stay longer for anything else or walk away, you are parking. And that is forbidden here."}},{"titel":"Here you may stop","text":"The side road has ended the no stopping rule. No side road, no zebra crossing, no driveway and no sign any more. Here you may stop and park. Indicate right, drive to the edge and stop."},{"titel":"To remember","text":"To park you need distance from junctions, zebra crossings and driveways, and there must be no sign forbidding stopping. If you are unsure, better drive one metre further."}]},
"einsatz":{"titel":"Emergency vehicle with blue light","kurz":"At a blue light and siren you clear the way at once. You keep right and do not block the junction.","phasen":[{"titel":"Blue light and siren","text":"Behind you an ambulance comes up with blue light and siren. That means everyone else must clear the way at once, no matter who would otherwise have priority.","frage":{"text":"Behind you comes an ambulance with blue light and siren. What do you do?","optionen":["I keep driving and accelerate","I stay calm, indicate right, drive to the right edge and stop","I stop in the middle of the road"],"erklaerung":"Clear the way at once. Indicate right, drive as far right as possible and stop, so the ambulance can pass."}},{"titel":"Pulling over to the right","text":"So, now you indicate right, drive to the right edge and stop. But before the junction, not in the middle of it. Whoever stands in the junction blocks the way of the emergency vehicle."},{"titel":"The ambulance overtakes","text":"The ambulance passes you, even using the oncoming lane. You stay put, do not move any more and do not follow it."},{"titel":"At the junction the cross traffic waits too","text":"At the junction the cross traffic waits too. The blue car comes from the right and would otherwise have priority. Now it has to wait. The emergency vehicle has a clear way.","frage":{"text":"The blue car comes from the right. May it drive into the junction before the ambulance?","optionen":["Yes, it may, priority to the right","No, it must wait, the ambulance has a clear way","Yes, it may, if it is fast"],"erklaerung":"Blue light with siren means a clear way. Everyone else waits, even whoever would otherwise have priority."}},{"titel":"Only when everything is clear","text":"The ambulance is through. Before you drive off, check whether a second emergency vehicle is coming. Then mirror, indicator left, and merge back in with a shoulder check."}]},
"einbahn":{"titel":"One-way street","kurz":"Drive only in the direction of the arrow. To turn left, move over to the left and let oncoming cyclists through","phasen":[{"titel":"The one-way street sign","text":"Look, the blue sign with the white arrow means one-way street. You may only drive in the direction of the arrow. Here you turn right into it.","frage":{"text":"What does the blue sign with the white arrow mean?","optionen":["I may only drive along the street in the direction of the arrow","I have priority in this street","I must turn into this street"],"erklaerung":"The sign shows a one-way street. Vehicles may only drive along it in the direction of the arrow."}},{"titel":"Move over to the left","text":"At the next junction you want to turn left. In a one-way street you move as far left as you can. First mirror, indicator left and shoulder check.","frage":{"text":"You want to turn left in the one-way street. Where do you position yourself?","optionen":["I move to the middle, as I usually do","I move as far left as I can","I stay over on the right"],"erklaerung":"On a road with traffic in one direction only, you move as far left as you can to turn left."}},{"titel":"Cyclists the other way","text":"Below the one-way street sign there is an extra sign. It shows that cyclists ride both ways here. One is already coming towards you. When you turn, always expect them.","frage":{"text":"A cyclist is coming towards you in the one-way street. Is that allowed?","optionen":["No, he is going the wrong way","Yes, cyclists may ride the other way here, the extra sign shows it","Only if he pushes his bike"],"erklaerung":"This one-way street is open to cyclists in the opposite direction. The extra sign on the one-way street sign shows this. Expect oncoming traffic on two wheels, especially when you turn."}},{"titel":"Let oncoming traffic through","text":"You are positioned on the left and you wait. Leave enough room on the left for cyclists from the front. When you turn left, you let oncoming vehicles go first, the cyclist too.","frage":{"text":"The cyclist is coming towards you, and you want to turn left. Who goes first?","optionen":["Me, because I am driving in the direction of the arrow","The cyclist, I let him through","Whoever reaches the junction first"],"erklaerung":"When you turn, you let oncoming vehicles go first. Cyclists riding the other way are oncoming traffic too."}},{"titel":"Turn and remember","text":"Now it is clear, and you turn left. By the way, in a one-way street you may also stop and park on the left. Anyone coming from the other end sees the no entry sign."}]},
"fahrradstrasse":{"titel":"Bicycle street","kurz":"The street belongs to cyclists. Cars only with an extra sign, speed thirty at most, never endanger or hold up cyclists","phasen":[{"titel":"Start of the bicycle street","text":"Look, a bicycle street starts here. It is meant for cyclists. You may drive your car in here because the sign below says motor vehicles permitted.","frage":{"text":"May you drive your car into a bicycle street?","optionen":["Yes, I may always drive in","I may only drive in if an extra sign allows it","No, I may never drive in"],"erklaerung":"Apart from bicycles and electric scooters, other vehicles may only use the bicycle street if an extra sign allows it."}},{"titel":"Access only or motor vehicles permitted","text":"If it says access only, you may only drive in if you have a reason to be there. For example, if you live here or visit someone. Motor vehicles permitted also lets you drive through.","frage":{"text":"The sign below says access only. You just want to take a shortcut. May you drive in?","optionen":["Yes, I may, it applies to everyone","No, I may only drive in if I have a reason to be there","Yes, I may if I drive slowly"],"erklaerung":"Access only means only those who have a reason to be there may drive in. With motor vehicles permitted, all motor vehicles may also drive through."}},{"titel":"Speed thirty, side by side allowed","text":"Here everyone may drive thirty at most. Cyclists may ride side by side. You must neither endanger them nor hold them up. If needed, you drive even slower.","frage":{"text":"The two cyclists are riding side by side. Is that allowed?","optionen":["No, they must ride one behind the other","Yes, in a bicycle street they may","Only if no car is coming"],"erklaerung":"In a bicycle street, cyclists may ride side by side. You adapt and drive slower if needed."}},{"titel":"Oncoming traffic, no overtaking yet","text":"A cyclist is coming from the front. There is no room to overtake now. You stay well back behind the two and adjust your speed."},{"titel":"Overtake with distance","text":"Now it is clear. Mirror, indicator left, shoulder check. Then you overtake and keep at least one and a half metres from the cyclists.","frage":{"text":"How much side distance do you need in town when you overtake cyclists?","optionen":["I think at least half a metre","I think at least one and a half metres","I think at least three metres"],"erklaerung":"When you overtake cyclists, you need at least one and a half metres side distance in town, and at least two metres outside town."}},{"titel":"End of the bicycle street","text":"Here the bicycle street ends, the sign is crossed out. From here the usual rules apply again. Of course you keep watching out for cyclists."}]},
"verkehrsberuhigt":{"titel":"Traffic-calmed area","kurz":"Walking pace, pedestrians and playing children everywhere. At the end, the others have priority","phasen":[{"titel":"Traffic-calmed area","text":"Look, the blue sign with a house, a child and a car. A traffic-calmed area starts here. From now on you only drive at walking pace.","frage":{"text":"How fast may you drive in a traffic-calmed area?","optionen":["I drive thirty at most","I drive at walking pace","I drive twenty at most"],"erklaerung":"In a traffic-calmed area you drive at walking pace, so about as fast as a person walks."}},{"titel":"Children may play everywhere","text":"Children may play anywhere here, even in the middle of the street. A ball rolls out, and the child runs after it. You stop and wait.","frage":{"text":"A ball rolls across the street in front of you, and a child runs after it. What do you do?","optionen":["I honk so that the child stops","I stop and wait","I drive slowly around the child"],"erklaerung":"You must neither endanger nor hold up pedestrians. If needed, you wait."}},{"titel":"Pedestrians across the whole width","text":"Pedestrians may use the whole street here. You must neither endanger them nor hold them up. If needed, you wait. But they must not hold you up for no reason either."},{"titel":"Parking only in marked spaces","text":"Here you may only park in the marked spaces, like the one on the left with the P. Otherwise you may only stop briefly, or longer to get in, get out, load and unload.","frage":{"text":"May you park in front of a house in a traffic-calmed area?","optionen":["Yes, I may park anywhere","No, I may only park in marked spaces","Yes, I may if I switch on the hazard lights"],"erklaerung":"You must not park outside the marked spaces. You may stop briefly, and longer to get in and out or to load and unload."}},{"titel":"The end, the others have priority","text":"At the end there is the sign with the red line through it. When you now drive onto the road, everyone else has priority. The car from the left too.","frage":{"text":"You are leaving the traffic-calmed area, and a car comes from the left. Who goes first?","optionen":["Me, priority to the right applies","The car from the left, I must let everyone through","Whoever is there first"],"erklaerung":"When you drive out of a traffic-calmed area onto the road, you must drive so that nobody is put in danger. Priority to the right does not apply here."}},{"titel":"Only when both sides are clear","text":"A car is coming from the right too. You wait until both sides are clear. Then you turn right and quickly get up to speed."}]},
"einfahrt_verboten":{"titel":"No entry","kurz":"Round and red with a white bar means do not drive in. Round and white with a red border means closed to all vehicles","phasen":[{"titel":"The no entry sign","text":"You want to turn right into the next street. But look, there is a round red sign with a white bar. That means no entry. You may not drive in here.","frage":{"text":"What does the round red sign with the white bar mean?","optionen":["I may not drive in here","I may only stop briefly here","I have priority here"],"erklaerung":"The sign means no entry. You may not drive in here with a vehicle."}},{"titel":"End of a one-way street","text":"This sign often stands at the end of a one-way street. Traffic comes towards you from there, like the blue car. Switch your indicator off straight away, or someone may rely on it."},{"titel":"Cyclists permitted","text":"Below the sign there is an extra sign, cyclists permitted. That is why the cyclist may ride in here. For you in the car, the ban still applies.","frage":{"text":"The cyclist turns into the street with the no entry sign. Is that allowed?","optionen":["No, the ban applies to everyone","Yes, the extra sign allows it for cyclists","Only if he rings his bell"],"erklaerung":"With the extra sign cyclists permitted, cyclists may ride in. For all other vehicles the ban applies."}},{"titel":"No vehicles of any kind","text":"On the left there is another sign, white with a red border. That means no vehicles of any kind. No vehicle may go in, not even a bicycle. You may push a bicycle or motorbike.","frage":{"text":"What is the difference between the two round signs?","optionen":["I think there is no difference","The white one closes the street to all vehicles, the red one only bans entry from this side","The white one only applies to trucks"],"erklaerung":"With no entry, traffic from the other direction drives as normal. With no vehicles of any kind, the street is closed to all vehicles. Bicycles and motorbikes may be pushed there."}},{"titel":"Where you often see the sign","text":"You often see the no entry sign at the end of one-way streets, at Autobahn exits and at car park exits. You drive straight on and only turn right at the next street.","frage":{"text":"Where do you often find the no entry sign?","optionen":["At the end of a one-way street","In front of every school","At every zebra crossing"],"erklaerung":"At the end of a one-way street, the sign stops anyone driving in the wrong way."}}]}};
